import { Select, HStack, Text, Input, VStack, Flex, Button, FormControl, FormLabel, Box, List, ListItem } from '@chakra-ui/react';
import React, { useState } from 'react';
import axios from 'axios';
import Navbar from './Navbar';

const Homescreen = () => {
  // State for the inputs
  const initialInputs = {
    location: '',
    lot: '',
    vendor: '',
    brand: '',
    species: '',
    description: '',
    grade: '',
    quantity: '',
    weight: '',
    packdate: '',
    temp: '',
    est: ''
  };

  const [inputs, setInputs] = useState(initialInputs);
  const [items, setItems] = useState([]);
  const [showDetails, setShowDetails] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [errorMessage, setErrorMessage] = useState('');

  // Generic input change handler
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInputs((prevInputs) => ({
      ...prevInputs,
      [name]: value,
    }));
  };

  // Clear form inputs
  const handleClear = () => setInputs(initialInputs);

  // Common API request handler
  const sendRequest = async (endpoint, successCallback) => {
    try {
      const result = await axios.post(`http://localhost:3001/${endpoint}`, { inputs });
      successCallback(result.data);
      setErrorMessage('');
    } catch (err) {
      console.error('Error:', err.response ? err.response.data : err.message);
      setErrorMessage(err.response ? err.response.data.error : 'An unexpected error occurred.');
      setItems([]);
      setShowDetails(false);
    }
  };

  const handleAdd = () => sendRequest('inventoryAdd', () => {
    handleClear();
    handleFind();
  });

  const handleFind = () => sendRequest('inventoryFind', (data) => {
    if (data.length === 0) {
      setErrorMessage('No items found. Please try different criteria.');
    } else {
      setItems(data.sort((a, b) => a.location.localeCompare(b.location)));
    }
  });

  const handleUpdate = async (e) => {
    e.preventDefault();
    if (window.confirm("Are you sure you want to update this item?")) {
      sendRequest('inventoryUpdate', (data) => {
        setItems([data]);
        handleClear();
      });
    }
  };

  const handleRemove = () => {
    if (window.confirm("Are you sure you want to delete this item?")) {
      sendRequest('inventoryRemove', handleClear);
    }
  };

  const handleSet = (item) => setInputs(item);

  // Display item details
  const handleItemClick = (item) => {
    setSelectedItem(item);
    setShowDetails(true);
  };

  return (
    <>
      <Navbar />
      <Flex width="100vw" height="100vh" alignItems="center" justifyContent="space-between" bg="lightblue" pt="60px">
        <Flex bg="lightblue" width="80%" height="90%" margin="10px" border="1px" direction="column" justifyContent="flex-start" alignItems="center" overflowY="auto">
          <FormControl width="100%">
            <VStack spacing={2} alignItems="center">
              {['Location', 'Lot', 'Vendor', 'Brand', 'Description'].map((field) => (
                <VStack spacing={1} width="75%" key={field}>
                  <FormLabel marginTop="5px" textAlign='left' marginBottom="5px">{field}</FormLabel>
                  <Input
                    name={field.toLowerCase()}
                    value={inputs[field.toLowerCase()]}
                    type='text'
                    bg="white"
                    width="100%"
                    placeholder={`Enter ${field}`}
                    onChange={handleInputChange}
                  />
                </VStack>
              ))}

              <HStack spacing={2} width="100%">
                <VStack spacing={1} width="33%">
                  <FormLabel marginTop="5px" marginBottom="5px">Species</FormLabel>
                  <Select name="species" value={inputs.species} bg="white" width="100%" placeholder='Select Species' onChange={handleInputChange}>
                    <option value='Beef'>Beef</option>
                    <option value='Pork'>Pork</option>
                    <option value='Chicken'>Chicken</option>
                    <option value='Lamb'>Lamb</option>
                  </Select>
                </VStack>
                <VStack spacing={1} width="33%">
                  <FormLabel marginTop="5px" marginBottom="5px">Grade</FormLabel>
                  <Select name="grade" value={inputs.grade} bg="white" width="100%" placeholder='Select Grade' onChange={handleInputChange}>
                    <option value='Wagyu'>Wagyu</option>
                    <option value='Prime'>Prime</option>
                    <option value='Choice'>Choice</option>
                    <option value='No Roll/Ongrade'>No Roll/Ongrade</option>
                    <option value='Select'>Select</option>
                    <option value='Other'>Other</option>
                  </Select>
                </VStack>
              </HStack>

              <HStack spacing={4} width="100%">
                {['Quantity', 'Weight', 'Pack Date', 'Temperature (°F)', 'EST#'].map((field) => (
                  <VStack spacing={1} width="32%" key={field}>
                    <FormLabel marginTop="5px" marginBottom="5px">{field}</FormLabel>
                    <Input
                      name={field.toLowerCase().replace(/[^a-z]/gi, '')}
                      value={inputs[field.toLowerCase().replace(/[^a-z]/gi, '')]}
                      type={field === 'Pack Date' ? 'date' : 'text'}
                      bg="white"
                      width="100%"
                      placeholder={`Enter ${field}`}
                      onChange={handleInputChange}
                    />
                  </VStack>
                ))}
              </HStack>
            </VStack>
          </FormControl>

          <Flex alignItems="center" justifyContent="center" mt="20px" width='100%'>
            <HStack spacing="5">
              <Button bg="green.200" margin="20px" onClick={handleAdd}>Add</Button>
              <Button bg="white" margin="20px" onClick={handleFind}>Find</Button>
              <Button bg="white" margin="20px" onClick={handleUpdate} type="submit">Update</Button>
              <Button bg="white" margin="20px" onClick={handleRemove}>Remove</Button>
              <Button bg="red.200" margin="20px" onClick={handleClear}>Clear</Button>
            </HStack>
          </Flex>
        </Flex>

        {/* Area for Object Displaying */}
        <VStack bg="lightblue" width="50%" height="90%" margin="10px" direction="column" justifyContent="flex-start" alignItems="center">
          <Flex bg="lightblue" width="100%" height="100%" margin="10px" border="1px" direction="column" justifyContent="flex-start" alignItems="center" overflowY="auto">
            {errorMessage && <Text color="red.500" mb={4}>{errorMessage}</Text>}
            <List spacing={3} width="90%">
              {items.map((item, index) => (
                <ListItem key={index} onClick={() => handleItemClick(item)}>
                  <Box p={3} shadow="md" borderWidth="1px" borderRadius="md" bg="white" cursor="pointer" _hover={{ bg: "gray.100" }}>
                    {`Item ${index + 1}: ${item.location} - ${item.description}`}
                  </Box>
                </ListItem>
              ))}
            </List>
            {showDetails && selectedItem && (
              <Box p={4} bg="white" borderWidth="1px" borderRadius="md" mt={4} width="90%">
                {Object.entries(selectedItem).map(([key, value]) => (
                  <Text key={key} fontWeight={key === 'location' ? 'bold' : 'normal'}>
                    {`${key.charAt(0).toUpperCase() + key.slice(1)}: ${value}`}
                  </Text>
                ))}
              </Box>
            )}
          </Flex>
        </VStack>
      </Flex>
    </>
  );
};

export default Homescreen;
